function fmtMoney(cents) {
  const abs = Math.abs(cents);
  const grouped = String(Math.floor(abs / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, " ");
  return (cents < 0 ? "-" : "") + grouped + "," + String(abs % 100).padStart(2, "0") + " €";
}
